const EPSILON: f32 = 1.0e-6;
const DAG_COMPLEXITY_NORMALIZER: f32 = 1.5;
const DIFFERENTIATION_P1: f32 = 31.0;
const DIFFERENTIATION_P2: f32 = 37.0;
const DIFFERENTIATION_MODULUS: f32 = 100.0;
const SOCIAL_REFERENCE_CACHE_CAPACITY: usize = 64;
const SOCIAL_REFERENCE_LOCAL_EVALUATION_LIMIT: usize = 100_000;
// Full multi-start coordinate refinement is useful for small reference
// states, but its cloned-state neighborhood scans become super-linear in both
// the number of request/function players and the player/candidate neighborhood.
// Bounded states retain the same policy-independent canonical social-greedy
// start and deterministic SA, with a fixed compute cap that makes formal
// reference construction executable.
const SOCIAL_REFERENCE_FULL_SEARCH_PLAYER_LIMIT: usize = 128;
const SOCIAL_REFERENCE_FULL_SEARCH_NEIGHBORHOOD_LIMIT: usize = 128;
const SOCIAL_REFERENCE_BOUNDED_SA_ITERATION_LIMIT: u32 = 256;
const OPERATIONAL_AFFINITY_HISTORY_LIMIT: usize = 64;
const OPERATIONAL_FAASRANK_HISTORY_LIMIT: usize = 256;
const OPERATIONAL_JIAGU_DEMAND_WINDOW: usize = 20;
const CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES: usize = 80;
const CAUSAL_ARRIVAL_SHOCK_RECENT_FRAMES: usize = 20;
const CAUSAL_ARRIVAL_SHOCK_HISTORY_FRAMES: usize =
    CAUSAL_ARRIVAL_SHOCK_BASELINE_FRAMES + CAUSAL_ARRIVAL_SHOCK_RECENT_FRAMES;
const CAUSAL_ARRIVAL_SHOCK_MIN_REQUESTS_PER_WINDOW: usize = 20;
const CAUSAL_ARRIVAL_SHOCK_ACTIVE_FRAMES: usize = 100;
// Version 3 fixes Eq. (8)'s state domain to the current-window players.
// Version 4 changes Eq. (6)'s queue observation to pending+runnable work.
// Version 5 makes the social reference independent of the evaluated policy's
// assignment by using a deterministic canonical SA starting allocation.
// Version 6 strengthens that policy-independent search with deterministic
// multi-start social local search and a candidate-scaled SA budget.
// Version 7 restores Eq. (6)'s stated normalization by defining q_max(t) as
// the maximum runnable backlog observed in the current scheduling window.
// Version 8 adds a deterministic Nash-feasible start to the policy-independent
// offline search so its lower bound includes both social-greedy and equilibrium
// constructions without reading the evaluated method's assignment.
// Version 9 keeps that full search bit-for-bit for at most 128 players and uses
// the canonical social-greedy start plus capped deterministic SA above that
// boundary, avoiding super-linear coordinate refinement on formal scale tests.
// Version 10 also bounds search when the player/candidate neighborhood exceeds
// 128, because moderate player counts with broad candidate sets exhibit the
// same super-linear cloned-state cost.  The bounded path uses at most 256
// deterministic SA moves and exactly recomputes its selected feasible state.
const REFERENCE_KEY_SCHEMA_VERSION: u64 = 10;
const REFERENCE_BUILD_RECORD_VERSION: u64 = 1;
const OPERATIONAL_ADAPTIVE_LOW_QUEUE_DENSITY: f32 = 32.0;
const OPERATIONAL_ADAPTIVE_HIGH_QUEUE_DENSITY: f32 = 96.0;

fn env_f32(name: &str, default: f32, min: f32, max: f32) -> f32 {
    env::var(name)
        .ok()
        .and_then(|value| value.parse::<f32>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(default)
        .clamp(min, max)
}

fn env_u32(name: &str, default: u32, min: u32, max: u32) -> u32 {
    env::var(name)
        .ok()
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or(default)
        .clamp(min, max)
}

fn load_name(env: &SimEnvObserve) -> &'static str {
    if env.help().config().request_freq_low() {
        "low"
    } else if env.help().config().request_freq_middle() {
        "middle"
    } else {
        "high"
    }
}

fn normalized_queue_pressure(pressure_queue_len: usize, queue_normalizer: f32) -> f32 {
    pressure_queue_len as f32 / queue_normalizer.max(EPSILON)
}

fn window_queue_normalizer<'a>(queue_lengths: impl Iterator<Item = &'a usize>) -> f32 {
    queue_lengths.copied().max().unwrap_or(0).max(1) as f32
}

fn jiagu_forecast_demand(history: &VecDeque<f64>) -> f64 {
    if history.is_empty() {
        return 0.0;
    }
    let mean = history.iter().sum::<f64>() / history.len() as f64;
    let trend = if history.len() > 1 {
        (history.back().copied().unwrap_or(0.0) - history.front().copied().unwrap_or(0.0))
            / (history.len() - 1) as f64
    } else {
        0.0
    };
    (mean + 0.5 * trend).max(0.0)
}

