    #[test]
    fn faasrank_orion_borda_uses_registered_vote_profiles() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.node_snapshots[0].pending_tasks = 9;
        scheduler.node_snapshots[1].pending_tasks = 0;
        let state = empty_operational_state();

        for votes in [1, 2] {
            assert!(
                scheduler.faasrank_orion_borda_operational_penalty(player, 1, &state, votes,)
                    < scheduler.faasrank_orion_borda_operational_penalty(player, 0, &state, votes,)
            );
        }
        assert_eq!(
            OperationalExpertProxy::FaasrankOrionBorda.as_str(),
            "faasrank_orion_borda"
        );
        assert_eq!(
            OperationalExpertProxy::Faasrank2OrionBorda.as_str(),
            "faasrank2_orion_borda"
        );
    }

    #[test]
    fn orion_ocs_borda_uses_exact_registered_votes() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.node_snapshots[0].pending_tasks = 9;
        scheduler.node_snapshots[1].pending_tasks = 0;
        let state = empty_operational_state();

        for (expert, orion_votes, ocs_votes, expected_name) in [
            (
                OperationalExpertProxy::OrionOcsBorda,
                1,
                1,
                "orion_ocs_borda",
            ),
            (
                OperationalExpertProxy::Orion2OcsBorda,
                2,
                1,
                "orion2_ocs_borda",
            ),
            (
                OperationalExpertProxy::OrionOcs2Borda,
                1,
                2,
                "orion_ocs2_borda",
            ),
        ] {
            scheduler.settings.operational_expert_proxy = expert;
            assert_eq!(expert.as_str(), expected_name);
            for node_id in [0, 1] {
                let orion_rank = scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                    scheduler.orion_load_faithful_operational_penalty(player, candidate, &state)
                });
                let ocs_rank = scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                    scheduler.ocs_current_demand_operational_penalty(player, candidate, &state)
                });
                let mut ranks = vec![orion_rank; orion_votes];
                ranks.extend(std::iter::repeat(ocs_rank).take(ocs_votes));
                let expected = scheduler.ordinal_borda_penalty(&ranks, 2);
                assert_eq!(
                    scheduler.orion_ocs_borda_operational_penalty(
                        player,
                        node_id,
                        &state,
                        orion_votes,
                        ocs_votes,
                    ),
                    expected
                );
                assert_eq!(
                    scheduler.operational_completion_penalty(player, node_id, &state, true),
                    expected
                );
            }
        }
    }

    #[test]
    fn faasrank_orion_load_least_borda_uses_exact_registered_votes() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.node_snapshots[0].pending_tasks = 9;
        scheduler.node_snapshots[1].pending_tasks = 0;
        let state = empty_operational_state();

        for (faasrank_votes, load_least_votes) in [(1, 1), (2, 1), (2, 2)] {
            for node_id in [0, 1] {
                let faasrank_rank =
                    scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                        scheduler.faasrank_operational_penalty(player, candidate, &state)
                    });
                let orion_rank = scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                    scheduler.orion_load_faithful_operational_penalty(player, candidate, &state)
                });
                let load_least_rank =
                    scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                        scheduler.load_least_current_demand_operational_penalty(candidate, &state)
                    });
                let mut ranks = vec![faasrank_rank; faasrank_votes];
                ranks.push(orion_rank);
                ranks.extend(std::iter::repeat(load_least_rank).take(load_least_votes));
                assert_eq!(
                    scheduler.faasrank_orion_load_least_borda_operational_penalty(
                        player,
                        node_id,
                        &state,
                        faasrank_votes,
                        load_least_votes,
                    ),
                    scheduler.ordinal_borda_penalty(&ranks, 2)
                );
            }
        }
        assert_eq!(
            OperationalExpertProxy::FaasrankOrionLoadLeastBorda.as_str(),
            "faasrank_orion_load_least_borda"
        );
        assert_eq!(
            OperationalExpertProxy::Faasrank2OrionLoadLeastBorda.as_str(),
            "faasrank2_orion_load_least_borda"
        );
        assert_eq!(
            OperationalExpertProxy::Faasrank2OrionLoadLeast2Borda.as_str(),
            "faasrank2_orion_load_least2_borda"
        );
    }

    #[test]
    fn hybrid3_expert_borda_keeps_three_exact_hybrid_votes() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.node_snapshots[0].pending_tasks = 7;
        scheduler.node_snapshots[1].pending_tasks = 1;
        scheduler.node_snapshots[0].utilization = 0.15;
        scheduler.node_snapshots[1].utilization = 0.65;
        scheduler.settings.operational_queue_weight = 0.20;
        scheduler.settings.operational_cold_start_weight = 0.55;
        scheduler.settings.operational_projected_load_weight = 1.0;
        scheduler.settings.operational_resource_weight = 0.15;
        scheduler.settings.operational_same_function_weight = 0.10;
        let state = empty_operational_state();

        for expert in [
            OperationalExpertProxy::Hybrid3FaasrankBorda,
            OperationalExpertProxy::Hybrid3OrionBorda,
            OperationalExpertProxy::Hybrid3JiaguBorda,
        ] {
            scheduler.settings.operational_expert_proxy = expert;
            for node_id in [0, 1] {
                let hybrid_rank =
                    scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                        scheduler.hybrid_operational_penalty(player, candidate, &state)
                    });
                let expert_rank =
                    scheduler.operational_ordinal_rank(player, node_id, |candidate| match expert {
                        OperationalExpertProxy::Hybrid3FaasrankBorda => {
                            scheduler.faasrank_operational_penalty(player, candidate, &state)
                        }
                        OperationalExpertProxy::Hybrid3OrionBorda => scheduler
                            .orion_load_faithful_operational_penalty(player, candidate, &state),
                        OperationalExpertProxy::Hybrid3JiaguBorda => scheduler
                            .jiagu_current_demand_operational_penalty(player, candidate, &state),
                        _ => unreachable!(),
                    });
                let expected = scheduler.ordinal_borda_penalty(
                    &[hybrid_rank, hybrid_rank, hybrid_rank, expert_rank],
                    2,
                );
                assert_eq!(
                    scheduler
                        .hybrid3_expert_borda_operational_penalty(player, node_id, &state, expert,),
                    expected
                );
                assert_eq!(
                    scheduler.operational_completion_penalty(player, node_id, &state, true),
                    expected
                );
            }
        }
        assert_eq!(
            OperationalExpertProxy::Hybrid3FaasrankBorda.as_str(),
            "hybrid3_faasrank_borda"
        );
        assert_eq!(
            OperationalExpertProxy::Hybrid3OrionBorda.as_str(),
            "hybrid3_orion_borda"
        );
        assert_eq!(
            OperationalExpertProxy::Hybrid3JiaguBorda.as_str(),
            "hybrid3_jiagu_borda"
        );
    }

