    #[test]
    fn jiagu_hiku_routers_switch_at_fixed_preplacement_queue_thresholds() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.player_function_demand.insert(player.fn_id, 2);
        let state = empty_operational_state();

        for (profile, name, threshold) in [
            (
                OperationalExpertProxy::JiaguHikuQueue24,
                "jiagu_hiku_queue24",
                24.0,
            ),
            (
                OperationalExpertProxy::JiaguHikuQueue48,
                "jiagu_hiku_queue48",
                48.0,
            ),
        ] {
            assert_eq!(profile.as_str(), name);
            assert!(!profile.uses_ready_frontier());

            scheduler.node_snapshots[0].pending_tasks = 2 * threshold as usize - 2;
            scheduler.node_snapshots[1].pending_tasks = 0;
            let jiagu = scheduler.jiagu_current_demand_operational_penalty(player, 0, &state);
            assert_eq!(
                scheduler.jiagu_hiku_queue_operational_penalty(player, 0, &state, true, threshold,),
                jiagu,
                "the below-threshold branch must be Jiagu"
            );

            scheduler.node_snapshots[0].pending_tasks = 2 * threshold as usize;
            let hiku = scheduler.hiku_load_faithful_operational_penalty(player, 0, &state, true);
            assert_eq!(
                scheduler.jiagu_hiku_queue_operational_penalty(player, 0, &state, true, threshold,),
                hiku,
                "the threshold belongs to the Hiku branch"
            );
        }
    }

    #[test]
    fn hiku_jiagu_borda_profiles_use_fixed_outcome_blind_votes() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.player_function_demand.insert(player.fn_id, 2);
        scheduler.node_snapshots[0].pending_tasks = 5;
        scheduler.node_snapshots[1].pending_tasks = 1;
        scheduler.node_snapshots[0].utilization = 0.2;
        scheduler.node_snapshots[1].utilization = 0.8;
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.existing_containers.insert((player.fn_id, 0));
        let state = empty_operational_state();

        for (profile, name, hiku_votes, jiagu_votes) in [
            (
                OperationalExpertProxy::HikuJiaguBorda,
                "hiku_jiagu_borda",
                1,
                1,
            ),
            (
                OperationalExpertProxy::Hiku2JiaguBorda,
                "hiku2_jiagu_borda",
                2,
                1,
            ),
            (
                OperationalExpertProxy::HikuJiagu2Borda,
                "hiku_jiagu2_borda",
                1,
                2,
            ),
        ] {
            assert_eq!(profile.as_str(), name);
            assert!(!profile.uses_ready_frontier());
            scheduler.settings.operational_expert_proxy = profile;
            for node_id in [0, 1] {
                let hiku_rank = scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                    scheduler
                        .hiku_load_faithful_operational_penalty(player, candidate, &state, true)
                });
                let jiagu_rank = scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                    scheduler.jiagu_current_demand_operational_penalty(player, candidate, &state)
                });
                let mut ranks = vec![hiku_rank; hiku_votes];
                ranks.extend(std::iter::repeat(jiagu_rank).take(jiagu_votes));
                let expected = scheduler.ordinal_borda_penalty(&ranks, 2);
                assert_eq!(
                    scheduler.hiku_jiagu_borda_operational_penalty(
                        player,
                        node_id,
                        &state,
                        true,
                        hiku_votes,
                        jiagu_votes,
                    ),
                    expected
                );
                assert_eq!(
                    scheduler.operational_completion_penalty(player, node_id, &state, true),
                    expected
                );
            }
        }
    }

    #[test]
    fn hiku_jiagu_queue_borda_routes_only_on_preregistered_density() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.player_function_demand.insert(player.fn_id, 2);
        scheduler.node_snapshots[0].utilization = 0.2;
        scheduler.node_snapshots[1].utilization = 0.8;
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.existing_containers.insert((player.fn_id, 0));
        let state = empty_operational_state();

        for (profile, name, threshold) in [
            (
                OperationalExpertProxy::Hiku2HighJiagu2LowQueue24Borda,
                "hiku2_high_jiagu2_low_queue24_borda",
                24.0,
            ),
            (
                OperationalExpertProxy::Hiku2HighJiagu2LowQueue48Borda,
                "hiku2_high_jiagu2_low_queue48_borda",
                48.0,
            ),
        ] {
            assert_eq!(profile.as_str(), name);
            assert!(!profile.uses_ready_frontier());
            scheduler.settings.operational_expert_proxy = profile;

            scheduler.node_snapshots[0].pending_tasks = 2 * threshold as usize - 2;
            scheduler.node_snapshots[1].pending_tasks = 0;
            let low_density = scheduler
                .hiku_jiagu_queue_borda_operational_penalties(player, &state, true, threshold);
            let jiagu_majority =
                scheduler.hiku_jiagu_borda_operational_penalties(player, &state, true, 1, 2);
            assert_eq!(low_density, jiagu_majority);
            for node_id in [0, 1] {
                assert_eq!(
                    scheduler.operational_completion_penalty(player, node_id, &state, true),
                    jiagu_majority[&node_id]
                );
            }

            scheduler.node_snapshots[0].pending_tasks = 2 * threshold as usize;
            let at_threshold = scheduler
                .hiku_jiagu_queue_borda_operational_penalties(player, &state, true, threshold);
            let hiku_majority =
                scheduler.hiku_jiagu_borda_operational_penalties(player, &state, true, 2, 1);
            assert_eq!(at_threshold, hiku_majority);
            for node_id in [0, 1] {
                assert_eq!(
                    scheduler.operational_completion_penalty(player, node_id, &state, true),
                    hiku_majority[&node_id]
                );
            }
        }
    }

    #[test]
    fn hiku_jiagu_borda_batch_matches_legacy_scores_for_every_candidate_order() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.node_snapshots = vec![NodeSnapshot::default(); 5];
        for (node_id, pending, resident, utilization) in [
            (0, 5, 0, 0.2),
            (1, 0, 3, 0.8),
            (2, 2, 1, 0.4),
            (3, 1, 0, 0.6),
            (4, 3, 2, 0.1),
        ] {
            scheduler.node_snapshots[node_id].pending_tasks = pending;
            scheduler.node_snapshots[node_id].resident_tasks = resident;
            scheduler.node_snapshots[node_id].utilization = utilization;
        }
        scheduler.player_function_demand.insert(player.fn_id, 3);
        scheduler.idle_warm_containers.insert((player.fn_id, 3));
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.warm_containers.insert((player.fn_id, 3));
        scheduler.existing_containers.insert((player.fn_id, 0));
        scheduler.existing_containers.insert((player.fn_id, 2));
        scheduler.existing_containers.insert((player.fn_id, 3));
        let state = AssignmentState::new(vec![NodeAggregate::default(); 5], 0);

        for candidates in [vec![0, 1, 2, 3, 4], vec![4, 2, 0, 3, 1]] {
            scheduler.feasible_nodes.insert(player, candidates.clone());

            let jiagu_batch = scheduler.jiagu_current_demand_operational_penalties(player, &state);
            for &node_id in &candidates {
                assert_eq!(
                    jiagu_batch[&node_id],
                    scheduler.jiagu_current_demand_operational_penalty(player, node_id, &state)
                );
            }

            let mut score_evaluations = 0;
            let ranks = scheduler.operational_ordinal_ranks(player, |node_id| {
                score_evaluations += 1;
                scheduler.node_snapshots[node_id].utilization
            });
            assert_eq!(score_evaluations, candidates.len());
            for &node_id in &candidates {
                let scalar_rank =
                    scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                        scheduler.node_snapshots[candidate].utilization
                    });
                assert_eq!(ranks[&node_id], scalar_rank);
            }

            for (hiku_votes, jiagu_votes) in [(1, 1), (2, 1), (1, 2)] {
                let batch = scheduler.hiku_jiagu_borda_operational_penalties(
                    player,
                    &state,
                    true,
                    hiku_votes,
                    jiagu_votes,
                );
                for &node_id in &candidates {
                    let hiku_rank =
                        scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                            scheduler.hiku_load_faithful_operational_penalty(
                                player, candidate, &state, true,
                            )
                        });
                    let jiagu_rank =
                        scheduler.operational_ordinal_rank(player, node_id, |candidate| {
                            scheduler
                                .jiagu_current_demand_operational_penalty(player, candidate, &state)
                        });
                    let mut legacy_ranks = vec![hiku_rank; hiku_votes];
                    legacy_ranks.extend(std::iter::repeat(jiagu_rank).take(jiagu_votes));
                    let legacy = scheduler.ordinal_borda_penalty(&legacy_ranks, candidates.len());
                    assert_eq!(batch[&node_id], legacy);
                    assert_eq!(
                        scheduler.hiku_jiagu_borda_operational_penalty(
                            player,
                            node_id,
                            &state,
                            true,
                            hiku_votes,
                            jiagu_votes,
                        ),
                        legacy
                    );
                }
            }
        }
    }

    #[test]
    fn jiagu_linear_rank_is_invariant_to_candidate_input_order() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.player_function_demand.insert(player.fn_id, 2);
        scheduler.node_snapshots[0].utilization = 0.7;
        scheduler.node_snapshots[1].utilization = 0.2;
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.existing_containers.insert((player.fn_id, 0));
        let state = empty_operational_state();

        scheduler.feasible_nodes.insert(player, vec![1, 0]);
        let reversed = (0..2)
            .map(|node_id| {
                scheduler.jiagu_current_demand_operational_penalty(player, node_id, &state)
            })
            .collect::<Vec<_>>();
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        let canonical = (0..2)
            .map(|node_id| {
                scheduler.jiagu_current_demand_operational_penalty(player, node_id, &state)
            })
            .collect::<Vec<_>>();

        assert_eq!(reversed, canonical);
        assert!(canonical.iter().all(|penalty| penalty.is_finite()));
    }

    #[test]
    fn jiagu_forecast_matches_baseline_mean_plus_trend_and_window() {
        let increasing = VecDeque::from([1.0, 2.0, 3.0]);
        let flat = VecDeque::from([2.0, 2.0, 2.0]);
        assert!(jiagu_forecast_demand(&increasing) > jiagu_forecast_demand(&flat));
        assert_eq!(jiagu_forecast_demand(&VecDeque::new()), 0.0);

        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.settings.operational_expert_proxy = OperationalExpertProxy::JiaguForecastFaithful;
        for frame in 0..25 {
            scheduler.player_function_demand.clear();
            scheduler
                .player_function_demand
                .insert(player.fn_id, frame + 1);
            scheduler.update_operational_jiagu_forecast(frame);
        }
        let history = scheduler
            .operational_jiagu_demand_history
            .get(&player.fn_id)
            .expect("forecast history");
        assert_eq!(history.len(), OPERATIONAL_JIAGU_DEMAND_WINDOW);
        assert_eq!(history.front().copied(), Some(6.0));
        assert_eq!(history.back().copied(), Some(25.0));
        assert_eq!(
            scheduler
                .operational_jiagu_predicted_demand
                .get(&player.fn_id)
                .copied(),
            Some(jiagu_forecast_demand(history))
        );
    }

