    #[test]
    fn v108_critical_service_proxy_matches_preregistered_current_state_formula() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.node_snapshots = vec![
            NodeSnapshot {
                cpu_capacity: 2.0,
                pending_tasks: 2,
                runnable_tasks: 3,
                resident_tasks: 4,
                ..NodeSnapshot::default()
            },
            NodeSnapshot {
                cpu_capacity: 4.0,
                runnable_tasks: 1,
                resident_tasks: 1,
                ..NodeSnapshot::default()
            },
        ];
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.warm_containers.insert((player.fn_id, 1));
        scheduler.function_parents.insert(player.fn_id, vec![2]);
        scheduler
            .function_profiles
            .insert(2, function_profile(2, 0.25, 0.25, 3));
        scheduler
            .player_parent_placements
            .insert(player, vec![(0, 20.0)]);
        scheduler.node_bandwidths = vec![vec![f32::INFINITY, 10.0], vec![10.0, f32::INFINITY]];
        let projected = PlayerId {
            req_id: player.req_id + 1,
            fn_id: player.fn_id,
        };
        let mut state = AssignmentState::new(vec![NodeAggregate::default(); 2], 2);
        state.assignments.insert(projected, 1);

        let anchor = scheduler
            .v108_critical_service_proxy(player, 0, &state)
            .expect("the local warm proxy is finite");
        let candidate = scheduler
            .v108_critical_service_proxy(player, 1, &state)
            .expect("the remote warm proxy is finite");
        // Anchor: (2 pending + 3 runnable + 4 resident + 0 projected + 1)
        // * 0.5 CPU work / 2 CPU capacity = 2.5 frames.
        assert!((anchor - 2.5).abs() < 1.0e-9);
        // Candidate: 20 MB / 10 MB/s +
        // (0 + 1 + 1 + 1 projected + 1) * 0.5 / 4 = 2.5.
        assert!((candidate - 2.5).abs() < 1.0e-9);

        scheduler.node_bandwidths[0][1] = 0.0;
        assert_eq!(
            scheduler.v108_critical_service_proxy(player, 1, &state),
            None
        );
        scheduler.node_bandwidths[0][1] = 10.0;
        scheduler.node_snapshots[1].cpu_capacity = 0.0;
        assert_eq!(
            scheduler.v108_critical_service_proxy(player, 1, &state),
            None
        );
        scheduler.node_snapshots[1].cpu_capacity = 4.0;
        scheduler.player_parent_placements.remove(&player);
        assert_eq!(
            scheduler.v108_critical_service_proxy(player, 1, &state),
            None
        );
    }

    #[test]
    fn v110_service_proxy_uses_exact_heterogeneous_queue_and_projected_work() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.settings.operational_expert_proxy = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15Horizon50ExactQueueWork10InitializerOnlyGuard64DualWindowSafePareto;
        scheduler.node_snapshots = vec![
            NodeSnapshot {
                cpu_capacity: 2.0,
                pending_cpu_work: Some(2.0),
                runnable_cpu_work: Some(3.0),
                runnable_remaining_cpu_work: Some(1.0),
                ..NodeSnapshot::default()
            },
            NodeSnapshot {
                cpu_capacity: 4.0,
                pending_cpu_work: Some(0.5),
                runnable_cpu_work: Some(0.25),
                runnable_remaining_cpu_work: Some(0.05),
                ..NodeSnapshot::default()
            },
        ];
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.warm_containers.insert((player.fn_id, 1));
        scheduler.function_parents.insert(player.fn_id, vec![2]);
        scheduler
            .function_profiles
            .insert(2, function_profile(2, 0.25, 0.25, 3));
        scheduler
            .function_profiles
            .insert(77, function_profile(77, 2.0, 0.25, 3));
        scheduler
            .player_parent_placements
            .insert(player, vec![(0, 20.0)]);
        scheduler.node_bandwidths = vec![vec![f32::INFINITY, 10.0], vec![10.0, f32::INFINITY]];
        let projected = PlayerId {
            req_id: player.req_id + 1,
            fn_id: 77,
        };
        let mut state = AssignmentState::new(vec![NodeAggregate::default(); 2], 2);
        state.assignments.insert(projected, 1);

        let anchor = scheduler
            .critical_service_proxy(player, 0, &state)
            .expect("exact local proxy is finite");
        let candidate = scheduler
            .critical_service_proxy(player, 1, &state)
            .expect("exact remote proxy is finite");
        // Anchor: (2.0 pending + 3.0 runnable + 0 projected + 0.5 current)
        // / 2 CPU capacity = 2.75 frames.
        assert!((anchor - 2.75).abs() < 1.0e-9);
        // Candidate: 20 MB / 10 MB/s +
        // (0.5 pending + 0.25 runnable + 2.0 projected + 0.5 current)
        // / 4 CPU capacity = 2.8125 frames.
        assert!((candidate - 2.8125).abs() < 1.0e-9);
        // The frozen V108 approximation observes only two count-based tasks
        // here and assigns both the current player's 0.5 CPU demand.
        assert!(
            (scheduler
                .v108_critical_service_proxy(player, 1, &state)
                .unwrap()
                - 2.25)
                .abs()
                < 1.0e-9
        );

        scheduler.node_snapshots[1].pending_cpu_work = None;
        assert_eq!(scheduler.critical_service_proxy(player, 1, &state), None);

        scheduler.node_snapshots[1].pending_cpu_work = Some(0.5);
        scheduler.settings.operational_expert_proxy = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15Horizon50RemainingQueueWork10InitializerOnlyGuard64DualWindowSafePareto;
        let remaining_anchor = scheduler
            .critical_service_proxy(player, 0, &state)
            .expect("remaining-work local proxy is finite");
        let remaining_candidate = scheduler
            .critical_service_proxy(player, 1, &state)
            .expect("remaining-work remote proxy is finite");
        // V111 changes only runnable work: anchor (2.0 + 1.0 + 0.5) / 2;
        // candidate 2 transfer + (0.5 + 0.05 + 2.0 + 0.5) / 4.
        assert!((remaining_anchor - 1.75).abs() < 1.0e-9);
        assert!((remaining_candidate - 2.7625).abs() < 1.0e-9);
        scheduler.node_snapshots[1].runnable_remaining_cpu_work = None;
        assert_eq!(scheduler.critical_service_proxy(player, 1, &state), None);

        scheduler.node_snapshots[0].pending_tasks = 2;
        scheduler.node_snapshots[0].runnable_tasks = 2;
        scheduler.node_snapshots[0].resident_tasks = 3;
        scheduler.node_snapshots[1].pending_tasks = 1;
        scheduler.node_snapshots[1].runnable_tasks = 2;
        scheduler.node_snapshots[1].resident_tasks = 3;
        scheduler.node_queue_cpu_works = vec![
            Some(NodeQueueCpuWork {
                pending_cpu: 2.25,
                resident_remaining_cpu: 5.1,
                pending_cpu_values: vec![0.25, 2.0],
                runnable_remaining_cpu_values: vec![0.1, 1.0],
                resident_remaining_cpu_values: vec![0.1, 1.0, 4.0],
                ..NodeQueueCpuWork::default()
            }),
            Some(NodeQueueCpuWork {
                pending_cpu: 0.5,
                resident_remaining_cpu: 5.05,
                pending_cpu_values: vec![0.5],
                runnable_remaining_cpu_values: vec![0.05, 2.0],
                resident_remaining_cpu_values: vec![0.05, 2.0, 3.0],
                ..NodeQueueCpuWork::default()
            }),
        ];
        scheduler.settings.operational_expert_proxy = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15Horizon50ProcessorSharingWork10InitializerOnlyGuard64DualWindowSafePareto;
        let processor_sharing_anchor = scheduler
            .critical_service_proxy(player, 0, &state)
            .expect("processor-sharing local proxy is finite");
        let processor_sharing_candidate = scheduler
            .critical_service_proxy(player, 1, &state)
            .expect("processor-sharing remote proxy is finite");
        // Current work is 0.5. Anchor competing work is
        // min(0.25,0.5)+min(2,0.5)+min(0.1,0.5)+min(1,0.5)=1.35;
        // adding the current 0.5 and dividing by capacity 2 gives 0.925.
        assert!((processor_sharing_anchor - 0.925).abs() < 1.0e-9);
        // Candidate adds 2 frames of transfer. Its competing work is
        // min(0.5,0.5)+min(0.05,0.5)+min(2,0.5)+min(projected 2,0.5)=1.55;
        // current work makes 2.05, divided by capacity 4 gives 0.5125.
        assert!((processor_sharing_candidate - 2.5125).abs() < 1.0e-9);

        scheduler.node_queue_cpu_works[1]
            .as_mut()
            .unwrap()
            .runnable_remaining_cpu_values
            .pop();
        assert_eq!(scheduler.critical_service_proxy(player, 1, &state), None);

        scheduler.node_queue_cpu_works[1]
            .as_mut()
            .unwrap()
            .runnable_remaining_cpu_values
            .push(2.0);
        scheduler.settings.operational_expert_proxy = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15Horizon50AdmittedWork10InitializerOnlyGuard64DualWindowSafePareto;
        let admitted_anchor = scheduler
            .critical_service_proxy(player, 0, &state)
            .expect("admitted-work local proxy is finite");
        let admitted_candidate = scheduler
            .critical_service_proxy(player, 1, &state)
            .expect("admitted-work remote proxy is finite");
        // Anchor: pending 2.25 + all resident residual 5.1 + current 0.5,
        // divided by capacity 2. Blocked resident work is included once.
        assert!((admitted_anchor - 3.925).abs() < 1.0e-9);
        // Candidate: 2 transfer + (pending 0.5 + all resident residual 5.05
        // + projected 2.0 + current 0.5) / capacity 4.
        assert!((admitted_candidate - 4.0125).abs() < 1.0e-9);

        scheduler.node_queue_cpu_works[1]
            .as_mut()
            .unwrap()
            .resident_remaining_cpu_values
            .pop();
        assert_eq!(scheduler.critical_service_proxy(player, 1, &state), None);
    }

    #[test]
    fn v108_critical_service_choice_obeys_exact_ratio_and_safety_gates() {
        let (mut scheduler, player) = operational_tie_scheduler();
        scheduler.settings.operational_expert_proxy = OperationalExpertProxy::
            FaasrankNativeFaithfulTerminalOcsSrptReadyCausalArrivalShock15CriticalService10InitializerOnlyGuard64DualWindowSafePareto;
        scheduler.feasible_nodes.insert(player, vec![0, 1]);
        scheduler.existing_containers.insert((player.fn_id, 0));
        scheduler.existing_containers.insert((player.fn_id, 1));
        scheduler.warm_containers.insert((player.fn_id, 0));
        scheduler.warm_containers.insert((player.fn_id, 1));
        scheduler.function_children.insert(player.fn_id, Vec::new());
        scheduler.terminal_functions.insert(player.fn_id);
        scheduler.available_container_memory = vec![1.0, 1.0];
        scheduler
            .player_node_locality_scores
            .insert((player, 0), 1.0);
        scheduler
            .player_node_locality_scores
            .insert((player, 1), 1.0);
        scheduler.node_snapshots = vec![
            NodeSnapshot {
                cpu_capacity: 1.0,
                pending_tasks: 9,
                cpu_utilization: 0.2,
                memory_utilization: 0.2,
                memory_limit: 1.0,
                ..NodeSnapshot::default()
            },
            NodeSnapshot {
                cpu_capacity: 1.0,
                pending_tasks: 8,
                cpu_utilization: 0.2,
                memory_utilization: 0.2,
                memory_limit: 1.0,
                ..NodeSnapshot::default()
            },
        ];
        let state = AssignmentState::new(vec![NodeAggregate::default(); 2], 1);

        let service10 = scheduler.v108_critical_service_choice(
            player,
            0,
            &[0, 1],
            &state,
            &VecDeque::new(),
            CriticalServiceProxyRatio {
                numerator: 9,
                denominator: 10,
            },
        );
        assert_eq!(service10.node_id, 1);
        assert!(service10.substituted);
        assert_eq!(service10.critical_service_proxy_evaluations, 1);
        assert_eq!(service10.critical_service_proxy_unavailable_count, 0);
        assert!((service10.anchor_critical_service_proxy.unwrap() - 5.0).abs() < 1.0e-9);
        assert!((service10.selected_critical_service_proxy.unwrap() - 4.5).abs() < 1.0e-9);

        let service20 = scheduler.v108_critical_service_choice(
            player,
            0,
            &[0, 1],
            &state,
            &VecDeque::new(),
            CriticalServiceProxyRatio {
                numerator: 4,
                denominator: 5,
            },
        );
        assert_eq!(service20.node_id, 0);
        assert!(!service20.substituted);

        scheduler.node_snapshots[1].cpu_utilization = 0.3;
        let resource_loss = scheduler.v108_critical_service_choice(
            player,
            0,
            &[0, 1],
            &state,
            &VecDeque::new(),
            CriticalServiceProxyRatio {
                numerator: 9,
                denominator: 10,
            },
        );
        assert_eq!(resource_loss.node_id, 0);
        assert!(!resource_loss.substituted);
        assert_eq!(resource_loss.cpu_headroom_rejected_candidate_count, 1);
    }

    #[test]
